"""Real-time two-way welcome crossfade and pause checks on an isolated server."""
import argparse,json
from pathlib import Path
from playwright.sync_api import sync_playwright
p=argparse.ArgumentParser();p.add_argument('--url',default='http://127.0.0.1:8094');p.add_argument('--cdp');p.add_argument('--output',default='validation/background-rotation');args=p.parse_args();out=Path(args.output);out.mkdir(parents=True,exist_ok=True)
with sync_playwright() as p:
 b=p.chromium.connect_over_cdp(args.cdp) if args.cdp else p.chromium.launch();ctx=b.new_context(viewport={'width':800,'height':480});pg=ctx.new_page();errors=[];pg.on('pageerror',lambda e:errors.append(str(e)));pg.goto(args.url);pg.wait_for_function('()=>document.querySelector("#connection").textContent.includes("Connected")');pg.wait_for_function('()=>document.querySelectorAll(".welcome-backdrop")[1].dataset.backgroundId!=="original"');pg.wait_for_function('()=>Number(document.querySelectorAll(".welcome-backdrop")[1].style.opacity)>.05&&Number(document.querySelectorAll(".welcome-backdrop")[1].style.opacity)<.8',timeout=27000);pg.screenshot(path=str(out/'crossfade.png'));pg.wait_for_function('()=>document.querySelector(".welcome-backdrop").dataset.backgroundId!=="original"&&Number(document.querySelector(".welcome-backdrop").style.opacity)>.83',timeout=6000)
 for w,h in [(800,480),(1280,720),(1920,1080)]:pg.set_viewport_size({'width':w,'height':h});pg.wait_for_timeout(200);pg.screenshot(path=str(out/f'webp-{w}.png'));assert pg.locator('#pumpkin').bounding_box()['height']>=48
 pg.click('#weather-location');pg.wait_for_timeout(200);before=pg.locator('.welcome-backdrop').evaluate_all('(els)=>els.map(e=>[e.dataset.backgroundId,e.style.opacity])');pg.wait_for_timeout(1500);assert pg.locator('.welcome-backdrop').evaluate_all('(els)=>els.map(e=>[e.dataset.backgroundId,e.style.opacity])')==before;pg.locator('#settings-dialog [data-close]').click();pg.wait_for_function('()=>document.querySelector(".welcome-backdrop").dataset.backgroundId==="original"&&Number(document.querySelector(".welcome-backdrop").style.opacity)>.83',timeout=29000)
 pg.evaluate("()=>fetch('/api/settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({reduced_motion:true})})");pg.wait_for_timeout(1300);before=pg.locator('.welcome-backdrop').evaluate_all('(els)=>els.map(e=>[e.dataset.backgroundId,e.style.opacity])');pg.wait_for_timeout(1500);assert pg.locator('.welcome-backdrop').evaluate_all('(els)=>els.map(e=>[e.dataset.backgroundId,e.style.opacity])')==before;pg.evaluate("()=>fetch('/api/settings',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify({reduced_motion:false})})");assert not errors,errors
 (out/'report.json').write_text(json.dumps({'real_time_original_to_webp_to_original':True,'fade_seconds':3,'hold_seconds':20,'modal_paused':True,'reduced_motion':True,'resolutions':[800,1280,1920],'errors':errors},indent=2));print('Two-way real-time background fades and pause checks passed');ctx.close()
 if not args.cdp:b.close()
